// Webhook adapter: convert the webhook request into the canonical RFQ input contract.
// The adapter knows only its source. Internal rfq_id and status are assigned by RFQ Intake.
const input = $input.first().json;
const body = input.body ?? {};

return [
  {
    json: {
      submission_id: body.submission_id,
      received_at: new Date().toISOString(),

      customer: {
        name: body.customer?.name,
        email: body.customer?.email,
      },

      source: {
        type: "webhook",
        reference: body.submission_id,
      },

      subject: body.subject,
      requested_delivery_date: body.requested_delivery_date,

      items: body.items,
    },
  },
];

// One import request from the API (JSON rows or a file) or the upload form (a file).
// The channel only turns the input into rows keyed by column headers; the core validates the data.
const item = $input.first();
const request = item.json;
const body = request.body ?? {};
const query = request.query ?? {};
const fromForm = $('Import Form Submitted').isExecuted;
const kind = String(body.kind ?? query.kind ?? "").trim();
const binaryKey = Object.keys(item.binary ?? {})[0];

const base = {
  kind,
  source: fromForm ? "upload_form" : "api",
  respond_as: fromForm ? "html" : "json",
};

if (binaryKey) {
  const file = item.binary[binaryKey];
  const filename = String(file.fileName ?? body.filename ?? query.filename ?? "file");
  const extension = filename.toLowerCase().match(/\.([a-z0-9]+)$/)?.[1] ?? "";
  const fileType = { xlsx: "xlsx", xls: "xls", csv: "csv", txt: "csv" }[extension] ?? "unsupported";
  return [{ json: { ...base, filename, file_type: fileType, binary_key: binaryKey }, binary: item.binary }];
}
if (Array.isArray(body.rows)) {
  return [{ json: { ...base, filename: body.filename ?? null, file_type: "rows", rows: body.rows } }];
}
return [{ json: { ...base, filename: null, file_type: "missing" } }];

// CSV exported from an ERP or Excel: UTF-8 (with or without BOM) or Windows-1250 (Polish Excel),
// delimiter ";" (Polish Excel), "," or tab — detected from the header line. Quoted fields per RFC 4180.
const request = $input.first().json;
const bytes = await this.helpers.getBinaryDataBuffer(0, request.binary_key);

let text;
try {
  text = new TextDecoder("utf-8", { fatal: true }).decode(bytes);
} catch {
  text = new TextDecoder("windows-1250").decode(bytes);
}
text = text.replace(/^﻿/, "");

function countOutsideQuotes(line, char) {
  let count = 0;
  let quoted = false;
  for (const c of line) {
    if (c === '"') quoted = !quoted;
    else if (c === char && !quoted) count++;
  }
  return count;
}
const headerLine = text.split(/\r?\n/, 1)[0] ?? "";
const delimiter = [";", ",", "\t"]
  .map(char => ({ char, count: countOutsideQuotes(headerLine, char) }))
  .sort((a, b) => b.count - a.count)[0].char;

// RFC 4180 parser: quotes, escaped quotes (""), delimiters and line breaks inside quotes.
const records = [];
let record = [];
let field = "";
let quoted = false;
for (let i = 0; i < text.length; i++) {
  const c = text[i];
  if (quoted) {
    if (c === '"' && text[i + 1] === '"') { field += '"'; i++; }
    else if (c === '"') quoted = false;
    else field += c;
  } else if (c === '"' && field === "") quoted = true;
  else if (c === delimiter) { record.push(field); field = ""; }
  else if (c === "\n" || c === "\r") {
    if (c === "\r" && text[i + 1] === "\n") i++;
    record.push(field); records.push(record); record = []; field = "";
  } else field += c;
}
if (field !== "" || record.length) { record.push(field); records.push(record); }
// Trailing empty lines are not data rows (empty lines inside the file stay and fail validation with their row number).
while (records.length && records[records.length - 1].every(value => value.trim() === "")) records.pop();

const headers = (records.shift() ?? []).map(h => h.trim());
const rows = records.map(values => {
  const row = {};
  headers.forEach((header, index) => {
    if (header !== "") row[header] = values[index] ?? "";
  });
  return row;
});

const { binary_key: binaryKey, file_type: fileType, ...command } = request;
return [{ json: { ...command, rows, parse_info: { delimiter, header_count: headers.length } } }];

// The first sheet, one item per row (header = row 1). An empty sheet gives no rows; the core rejects it.
const { binary_key: binaryKey, file_type: fileType, ...command } = $('Import Request').first().json;
const rows = $input.all().map(item => item.json).filter(row => Object.keys(row).length > 0);
return [{ json: { ...command, rows } }];

const request = $input.first().json;
const error = request.file_type === "unsupported"
  ? `Unsupported file "${request.filename}". Send CSV, XLSX or XLS.`
  : "Send a file (multipart field \"file\" with ?kind=...) or JSON { kind, rows: [...] }.";
return [{ json: { http_status: 422, body: { status: "REJECTED", kind: request.kind || null, error_count: 1, errors: [error] } } }];

// Result of the core (or of a request rejected by the channel): { http_status, body }.
const { http_status: httpStatus, body } = $input.first().json;
return [{ json: { http_status: httpStatus, body } }];

// Upload form (GET) and import result page (POST) — one Code node renders both, in the installation language.
const { language, recent } = $input.first().json;
const showResult = $('Import Form Submitted').isExecuted;

const TEXTS = {
  pl: {
    title: "Import danych",
    intro: "Wgraj pełny plik z ERP lub Excela (CSV, XLSX, XLS). Rekordy, których nie ma w pliku, zostaną dezaktywowane. Plik jest wgrywany w całości albo wcale.",
    kind: "Rodzaj danych",
    kinds: { catalogue: "Katalog produktów z cenami bazowymi", customers: "Klienci (e-maile / domeny, rabat)", customer_prices: "Ceny indywidualne klientów" },
    file: "Plik",
    submit: "Importuj",
    recent: "Ostatnie importy",
    columns: ["Czas", "Rodzaj", "Źródło", "Plik", "Status", "Wiersze", "Wynik"],
    status: { APPLIED: "Zaimportowano", DUPLICATE: "Bez zmian — te dane były już zaimportowane", REJECTED: "Odrzucono — nic nie zostało zmienione" },
    summary: {
      products_inserted: "nowe produkty", products_updated: "zmienione produkty", products_deactivated: "dezaktywowane produkty",
      prices_changed: "zmienione ceny", prices_deactivated: "dezaktywowane ceny",
      customers_inserted: "nowi klienci", customers_updated: "zmienieni klienci", customers_deactivated: "dezaktywowani klienci",
      customer_prices_deactivated: "dezaktywowane ceny klientów",
      prices_inserted: "nowe ceny", prices_updated: "zmienione ceny",
    },
    errors: "Błędy (numer wiersza jak w arkuszu, nagłówek = wiersz 1)",
    more_errors: "… i {count} kolejnych.",
    back: "Wróć do formularza",
    rows: "Wiersze",
  },
  en: {
    title: "Data import",
    intro: "Upload a complete file from the ERP or Excel (CSV, XLSX, XLS). Records missing from the file are deactivated. The file is applied completely or not at all.",
    kind: "Data",
    kinds: { catalogue: "Product catalogue with base prices", customers: "Customers (emails / domains, discount)", customer_prices: "Customer-specific prices" },
    file: "File",
    submit: "Import",
    recent: "Recent imports",
    columns: ["Time", "Data", "Source", "File", "Status", "Rows", "Result"],
    status: { APPLIED: "Imported", DUPLICATE: "No change — this data was already imported", REJECTED: "Rejected — nothing was changed" },
    summary: {},
    errors: "Errors (row numbers as in the spreadsheet, header = row 1)",
    more_errors: "… and {count} more.",
    back: "Back to the form",
    rows: "Rows",
  },
};
const t = TEXTS[language] ?? TEXTS.en;

function escapeHtml(value) {
  return String(value ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}
// Times in the installation time zone (n8n GENERIC_TIMEZONE / TIMEZONE in .env), with the offset shown.
const localTime = value => DateTime.fromISO(String(value)).toFormat("yyyy-MM-dd HH:mm '(UTC'ZZ')'");
const summaryText = summary => Object.entries(summary ?? {})
  .filter(([, count]) => Number(count) > 0)
  .map(([key, count]) => `${t.summary[key] ?? key.replaceAll("_", " ")}: ${count}`)
  .join(", ") || "—";
function page(body, httpStatus = 200) {
  const html = `<!doctype html>
<html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>${escapeHtml(t.title)}</title>
<style>
  html { color-scheme: light; } body { font-family: Arial, sans-serif; font-size: 15px; color: #222; background: #fff; max-width: 900px; margin: 24px auto; padding: 0 16px; }
  label { display: block; margin: 12px 0 4px; font-weight: bold; }
  select, input[type=file] { width: 100%; padding: 6px; box-sizing: border-box; }
  .box { background: #f4f4f4; padding: 10px 12px; margin: 12px 0; }
  .ok { border-left: 4px solid #2e7d32; } .bad { border-left: 4px solid #c62828; }
  button { margin-top: 16px; padding: 8px 16px; font-size: 15px; }
  table { border-collapse: collapse; width: 100%; font-size: 13px; margin-top: 8px; }
  th, td { border-bottom: 1px solid #ddd; padding: 4px 6px; text-align: left; vertical-align: top; }
  .wrap { overflow-x: auto; }
</style></head><body><h1>${escapeHtml(t.title)}</h1>${body}</body></html>`;
  return [{ json: { html, http_status: httpStatus } }];
}

if (showResult) {
  const { http_status: httpStatus, body } = $('Import Result').first().json;
  const good = body.status === "APPLIED" || body.status === "DUPLICATE";
  const errors = body.errors ?? [];
  const errorList = errors.length
    ? `<p><b>${escapeHtml(t.errors)}</b></p><ul>${errors.map(e => `<li>${escapeHtml(e)}</li>`).join("")}</ul>` +
      (body.error_count > errors.length ? `<p>${escapeHtml(t.more_errors.replace("{count}", body.error_count - errors.length))}</p>` : "")
    : "";
  const kindLabel = t.kinds[body.kind] ?? body.kind ?? "";
  return page(`
  <div class="box ${good ? "ok" : "bad"}">
    <b>${escapeHtml(t.status[body.status] ?? body.status)}</b>${kindLabel ? ` — ${escapeHtml(kindLabel)}` : ""}<br>
    ${body.row_count !== undefined ? `${escapeHtml(t.rows)}: ${escapeHtml(body.row_count)}<br>` : ""}
    ${body.summary ? escapeHtml(summaryText(body.summary)) : ""}
  </div>
  ${errorList}
  <p><a href="">${escapeHtml(t.back)}</a></p>`, httpStatus);
}

const options = Object.entries(t.kinds)
  .map(([value, label]) => `<option value="${value}">${escapeHtml(label)}</option>`).join("");
const history = (recent ?? []).map(batch => `<tr>
  <td>${escapeHtml(localTime(batch.created_at))}</td>
  <td>${escapeHtml(t.kinds[batch.kind] ?? batch.kind)}</td>
  <td>${escapeHtml(batch.source)}</td>
  <td>${escapeHtml(batch.filename ?? "")}</td>
  <td>${escapeHtml(t.status[batch.status]?.split(" — ")[0] ?? batch.status)}</td>
  <td>${escapeHtml(batch.row_count)}</td>
  <td>${escapeHtml(batch.status === "APPLIED" ? summaryText(batch.summary) : (batch.errors ?? [])[0] ?? "")}</td>
</tr>`).join("");

return page(`
  <p>${escapeHtml(t.intro)}</p>
  <form method="post" action="" enctype="multipart/form-data">
    <label for="kind">${escapeHtml(t.kind)}</label>
    <select id="kind" name="kind" required>${options}</select>
    <label for="file">${escapeHtml(t.file)}</label>
    <input type="file" id="file" name="file" accept=".csv,.txt,.xlsx,.xls" required>
    <button type="submit">${escapeHtml(t.submit)}</button>
  </form>
  ${history ? `<h2>${escapeHtml(t.recent)}</h2><div class="wrap"><table><tr>${t.columns.map(c => `<th>${escapeHtml(c)}</th>`).join("")}</tr>${history}</table></div>` : ""}`);

// Every API call carries the installation's API key: header X-API-Key or Authorization: Bearer <key>.
// Webhook-level n8n credentials would answer 403 in n8n's own format; this gate answers 401 in ours.
const request = $input.first().json;
const headers = request.headers ?? {};
const bearer = String(headers.authorization ?? "").match(/^Bearer\s+(.+)$/i)?.[1];
const apiKey = String(headers["x-api-key"] ?? bearer ?? "").trim();
const endpoint = $('RFQ Webhook').isExecuted ? "rfq"
  : $('Review Decision Webhook').isExecuted ? "rfq-review"
  : "quote-decision";
return [{ json: { endpoint, api_key: apiKey || null, request } }];

// The original webhook request continues to its lane.
const { endpoint, request } = $('API Request').first().json;
return [{ json: { ...request, endpoint } }];
